interface AsyncState<T> {
  data: T | null;
  loading: boolean;
  error: Error | null;
}

function useAsync<T>(asyncFn: () => Promise<T>, deps: any[] = []) {
  const [state, setState] = useState<AsyncState<T>>({
    data: null,
    loading: true,
    error: null,
  });

  useEffect(() => {
    let cancelled = false;

    setState({ data: null, loading: true, error: null });

    asyncFn()
      .then(data => {
        if (!cancelled) {
          setState({ data, loading: false, error: null });
        }
      })
      .catch(error => {
        if (!cancelled) {
          setState({ data: null, loading: false, error });
        }
      });

    return () => { cancelled = true; };
  }, deps);

  const retry = useCallback(() => {
    setState({ data: null, loading: true, error: null });
  }, []);

  return { ...state, retry };
}

// Usage
function UserProfile({ userId }: { userId: string }) {
  const { data, loading, error, retry } = useAsync(
    () => fetch(`/api/users/${userId}`).then(r => r.json()),
    [userId]
  );

  if (loading) return <Spinner />;
  if (error) return <ErrorView error={error} onRetry={retry} />;
  return <Profile data={data!} />;
}

function useRetryableQuery<T>(asyncFn: () => Promise<T>, maxRetries = 3) {
  const [attempt, setAttempt] = useState(0);
  const [error, setError] = useState<Error | null>(null);
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;

    const execute = async () => {
      try {
        const result = await asyncFn();
        if (!cancelled) {
          setData(result);
          setLoading(false);
        }
      } catch (err) {
        if (cancelled) return;

        if (attempt < maxRetries) {
          const delay = Math.min(1000 * 2 ** attempt, 10000);
          setTimeout(() => setAttempt(a => a + 1), delay);
        } else {
          setError(err as Error);
          setLoading(false);
        }
      }
    };

    execute();

    return () => { cancelled = true; };
  }, [attempt, asyncFn, maxRetries]);

  const reset = useCallback(() => {
    setAttempt(0);
    setError(null);
    setData(null);
    setLoading(true);
  }, []);

  return { data, loading, error, retry: reset };
}

function useCachedQuery<T>(key: string, fetcher: () => Promise<T>) {
  const [state, setState] = useState<AsyncState<T> & { cached: T | null }>({
    data: null,
    cached: null,
    loading: true,
    error: null,
  });

  useEffect(() => {
    const cached = sessionStorage.getItem(`cache-${key}`);
    let initial: T | null = null;

    if (cached) {
      initial = JSON.parse(cached);
      setState(s => ({ ...s, cached: initial, data: initial }));
    }

    fetcher()
      .then(data => {
        sessionStorage.setItem(`cache-${key}`, JSON.stringify(data));
        setState({ data, cached: initial, loading: false, error: null });
      })
      .catch(error => {
        setState({
          data: initial, // Show cached data
          cached: initial,
          loading: false,
          error,
        });
      });
  }, [key, fetcher]);

  return {
    data: state.data,
    cached: state.cached,
    loading: state.loading,
    error: state.error,
    isStale: state.error !== null && state.cached !== null,
  };
}

// React Component Example with Hooks
import React, { useState, useEffect, useCallback } from 'react';

function DataFetcher({ endpoint }) {
  // State management with useState
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // useCallback for memoized fetch function
  const fetchData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(endpoint);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const result = await response.json();
      setData(result);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [endpoint]);

  // useEffect for side effects
  useEffect(() => {
    fetchData();
  }, [fetchData]);

  if (loading) return <div className="loading">Loading...</div>;
  if (error) return <div className="error">Error: {error}</div>;

  return (
    <div className="data-container">
      <h2>Fetched Data</h2>
      <pre>{JSON.stringify(data, null, 2)}</pre>
    </div>
  );
}

export default DataFetcher;
